using ClosedXML.Excel;using Indamin.Payment.Data;
namespace Indamin.Payment.Services;
public class ExcelService{
 public List<PartImportRow> ReadParts(Stream stream,IReadOnlyDictionary<string,int> types,out List<string> errors){errors=[];using var wb=new XLWorkbook(stream);var ws=wb.Worksheet(1);var h=Headers(ws.Row(1));foreach(var x in new[]{"کد قطعه","عنوان قطعه","نوع قطعه","فعال یا غیرفعال بودن"})Require(h,errors,x);if(errors.Count>0)return[];var r=new List<PartImportRow>();foreach(var row in ws.RowsUsed().Skip(1)){var n=row.RowNumber();var code=Cell(ws,n,h["کد قطعه"]);if(code=="")continue;var title=Cell(ws,n,h["عنوان قطعه"]);var t=Cell(ws,n,h["نوع قطعه"]);if(!types.TryGetValue(Norm(t),out var id)){errors.Add($"سطر {n}: نوع قطعه «{t}» تعریف نشده است.");continue;}r.Add(new PartImportRow(n,code,title,id,Bool(Cell(ws,n,h["فعال یا غیرفعال بودن"]))));}return r;}
 public List<SupplierImportRow> ReadSuppliers(Stream stream,IReadOnlyDictionary<string,int> acts,out List<string> errors){errors=[];using var wb=new XLWorkbook(stream);var ws=wb.Worksheet(1);var h=Headers(ws.Row(1));foreach(var x in new[]{"کد تامین کننده","عنوان تامین کننده","مبلغ مطالبات استقراری","حوزه فعالیت","فعال یا غیرفعال بودن"})Require(h,errors,x);if(errors.Count>0)return[];var r=new List<SupplierImportRow>();foreach(var row in ws.RowsUsed().Skip(1)){var n=row.RowNumber();var code=Cell(ws,n,h["کد تامین کننده"]);if(code=="")continue;var title=Cell(ws,n,h["عنوان تامین کننده"]);decimal opening;try{opening=ReadDecimal(ws.Cell(n,h["مبلغ مطالبات استقراری"]));}catch{errors.Add($"سطر {n}: مبلغ مطالبات استقراری نامعتبر است.");continue;}if(opening<0){errors.Add($"سطر {n}: مبلغ مطالبات استقراری نمی‌تواند منفی باشد.");continue;}var ids=Cell(ws,n,h["حوزه فعالیت"]).Split(new[]{';','،',',','|'},StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries).Select(x=>acts.TryGetValue(Norm(x),out var id)?id:0).ToList();if(ids.Any(x=>x==0)){errors.Add($"سطر {n}: یکی از حوزه‌های فعالیت تعریف نشده است.");continue;}r.Add(new SupplierImportRow(n,code,title,opening,ids.Distinct().ToList(),Bool(Cell(ws,n,h["فعال یا غیرفعال بودن"]))));}return r;}
 public List<SupplierPartImportRow> ReadSupplierParts(Stream stream,IReadOnlyDictionary<string,int> suppliers,IReadOnlyDictionary<string,int> parts,out List<string> errors){errors=[];using var wb=new XLWorkbook(stream);var ws=wb.Worksheet(1);var h=Headers(ws.Row(1));foreach(var x in new[]{"کد تامین کننده","کد قطعه","ظرفیت تامین","مهلت تسویه (روز)","فعال یا غیرفعال بودن"})Require(h,errors,x);if(errors.Count>0)return[];var r=new List<SupplierPartImportRow>();foreach(var row in ws.RowsUsed().Skip(1)){var n=row.RowNumber();var sc=Cell(ws,n,h["کد تامین کننده"]);var pc=Cell(ws,n,h["کد قطعه"]);if(sc==""&&pc=="")continue;if(!suppliers.TryGetValue(Norm(sc),out var sid)){errors.Add($"سطر {n}: کد تامین‌کننده «{sc}» تعریف نشده است.");continue;}if(!parts.TryGetValue(Norm(pc),out var pid)){errors.Add($"سطر {n}: کد قطعه «{pc}» تعریف نشده است.");continue;}decimal capacity;try{capacity=ReadDecimal(ws.Cell(n,h["ظرفیت تامین"]));}catch{errors.Add($"سطر {n}: ظرفیت تامین نامعتبر است.");continue;}if(capacity<0){errors.Add($"سطر {n}: ظرفیت تامین نمی‌تواند منفی باشد.");continue;}if(!int.TryParse(PersianDateService.ToLatinDigits(Cell(ws,n,h["مهلت تسویه (روز)"])),out var days)||days<=0){errors.Add($"سطر {n}: مهلت تسویه باید عددی بزرگ‌تر از صفر باشد.");continue;}r.Add(new SupplierPartImportRow(n,sid,pid,Math.Round(capacity,2),days,Bool(Cell(ws,n,h["فعال یا غیرفعال بودن"]))));}return r;}
 public List<ImportedPaymentInvoice> ReadPaymentInvoices(Stream stream,Func<string,DateTime> parseDate,out List<string> errors){errors=[];using var wb=new XLWorkbook(stream);var ws=wb.Worksheet(1);var h=Headers(ws.Row(1));foreach(var x in new[]{"شماره رسید","انبار","نام کالا","نام تامین کننده","مبلغ بدهی","تاریخ رسید"})Require(h,errors,x);if(errors.Count>0)return[];var r=new List<ImportedPaymentInvoice>();foreach(var row in ws.RowsUsed().Skip(1)){var n=row.RowNumber();var receipt=Cell(ws,n,h["شماره رسید"]);if(receipt=="")continue;var warehouse=Cell(ws,n,h["انبار"]);var part=Cell(ws,n,h["نام کالا"]);var sup=Cell(ws,n,h["نام تامین کننده"]);if(warehouse==""||part==""||sup==""){errors.Add($"سطر {n}: انبار، نام کالا و نام تامین‌کننده الزامی است.");continue;}decimal debt;try{debt=ReadDecimal(ws.Cell(n,h["مبلغ بدهی"]));}catch{errors.Add($"سطر {n}: مبلغ بدهی نامعتبر است.");continue;}if(debt<=0)continue;DateTime date;try{var c=ws.Cell(n,h["تاریخ رسید"]);date=c.DataType==XLDataType.DateTime?c.GetDateTime().Date:parseDate(c.GetString()).Date;}catch{errors.Add($"سطر {n}: تاریخ رسید نامعتبر است.");continue;}r.Add(new ImportedPaymentInvoice(n,receipt,warehouse,part,sup,Math.Round(debt,2),date));}return r;}
 public byte[] Parts(IEnumerable<Part> rows){using var wb=new XLWorkbook();var ws=wb.Worksheets.Add("کالاها");var h=new[]{"کد قطعه","عنوان قطعه","نوع قطعه","فعال یا غیرفعال بودن"};for(var i=0;i<h.Length;i++)ws.Cell(1,i+1).Value=h[i];var n=2;foreach(var x in rows){ws.Cell(n,1).Value=x.Code;ws.Cell(n,2).Value=x.Title;ws.Cell(n,3).Value=x.Type?.Title??"";ws.Cell(n,4).Value=x.IsActive?"فعال":"غیرفعال";n++;}Style(ws);return Bytes(wb);}
 public byte[] Suppliers(IEnumerable<Supplier> rows){using var wb=new XLWorkbook();var ws=wb.Worksheets.Add("تامین‌کنندگان");var h=new[]{"کد تامین کننده","عنوان تامین کننده","مبلغ مطالبات استقراری","حوزه فعالیت","فعال یا غیرفعال بودن"};for(var i=0;i<h.Length;i++)ws.Cell(1,i+1).Value=h[i];var n=2;foreach(var x in rows){ws.Cell(n,1).Value=x.Code;ws.Cell(n,2).Value=x.Title;ws.Cell(n,3).Value=x.InitialClaimAmount;ws.Cell(n,4).Value=string.Join("؛ ",x.Activities.Where(a=>a.Activity!=null).Select(a=>a.Activity!.Title));ws.Cell(n,5).Value=x.IsActive?"فعال":"غیرفعال";n++;}Style(ws);return Bytes(wb);}
 public byte[] SupplierParts(IEnumerable<SupplierPart> rows){using var wb=new XLWorkbook();var ws=wb.Worksheets.Add("ارتباط کالا و تامین‌کننده");var h=new[]{"کد تامین کننده","عنوان تامین کننده","کد قطعه","عنوان قطعه","ظرفیت تامین","مهلت تسویه (روز)","فعال یا غیرفعال بودن"};for(var i=0;i<h.Length;i++)ws.Cell(1,i+1).Value=h[i];var n=2;foreach(var x in rows){ws.Cell(n,1).Value=x.Supplier?.Code??"";ws.Cell(n,2).Value=x.Supplier?.Title??"";ws.Cell(n,3).Value=x.Part?.Code??"";ws.Cell(n,4).Value=x.Part?.Title??"";ws.Cell(n,5).Value=x.SupplyCapacity;ws.Cell(n,6).Value=x.ContractSettlementDays;ws.Cell(n,7).Value=x.IsActive?"فعال":"غیرفعال";n++;}Style(ws);return Bytes(wb);}
 public byte[] PaymentRows(IEnumerable<PaymentCalculationRow> rows,IEnumerable<PaymentParameterSnapshot> ps){using var wb=new XLWorkbook();var ws=wb.Worksheets.Add("محاسبه تخصیص");var hs=new List<string>{"شماره رسید","انبار","نام کالا","نام تامین کننده","مبلغ بدهی اولیه","تخصیص قبلی","مانده بدهی","مانده بدهی تامین‌کننده","مهلت قراردادی","سن بدهی"};hs.AddRange(ps.Select(x=>x.Title));hs.AddRange(new[]{"امتیاز نهایی وزنی","ضریب تخصیص","تخصیص مرحله دوم","مبلغ قابل تخصیص نهایی"});for(var i=0;i<hs.Count;i++)ws.Cell(1,i+1).Value=hs[i];var n=2;foreach(var x in rows){var c=1;ws.Cell(n,c++).Value=x.ReceiptNo;ws.Cell(n,c++).Value=x.Warehouse;ws.Cell(n,c++).Value=x.PartTitle;ws.Cell(n,c++).Value=x.SupplierTitle;ws.Cell(n,c++).Value=x.OriginalDebt;ws.Cell(n,c++).Value=x.PreviousAllocated;ws.Cell(n,c++).Value=x.RemainingDebt;ws.Cell(n,c++).Value=x.SupplierOutstandingDebt;ws.Cell(n,c++).Value=x.ContractSettlementDays;ws.Cell(n,c++).Value=x.DebtAgeDays;foreach(var p in ps)ws.Cell(n,c++).Value=x.Scores.FirstOrDefault(s=>s.ParameterId==p.Id)?.Score??0;ws.Cell(n,c++).Value=x.WeightedScore;ws.Cell(n,c++).Value=x.AllocationRatio;ws.Cell(n,c++).Value=x.CalculatedAllocatedAmount;ws.Cell(n,c++).Value=x.AllocatedAmount;n++;}Style(ws);return Bytes(wb);}
 public byte[] SupplierPartEvaluations(IEnumerable<SupplierPart> mappings,IEnumerable<PaymentParameter> parameters,IEnumerable<SupplierPartEvaluation> scores){using var wb=new XLWorkbook();var ws=wb.Worksheets.Add("ارزیابی قطعه-تامین‌کننده");var ps=parameters.ToList();var hs=new List<string>{"کد تامین کننده","عنوان تامین کننده","کد قطعه","عنوان قطعه","وضعیت ارزیابی"};hs.AddRange(ps.Select(x=>x.Title));for(var i=0;i<hs.Count;i++)ws.Cell(1,i+1).Value=hs[i];var scoreList=scores.ToList();var n=2;foreach(var m in mappings){var c=1;ws.Cell(n,c++).Value=m.Supplier?.Code??"";ws.Cell(n,c++).Value=m.Supplier?.Title??"";ws.Cell(n,c++).Value=m.Part?.Code??"";ws.Cell(n,c++).Value=m.Part?.Title??"";var active=ps.Count==0||ps.All(p=>scoreList.Any(x=>x.SupplierPartId==m.Id&&x.PaymentParameterId==p.Id&&x.IsActive));ws.Cell(n,c++).Value=active?"فعال":"غیرفعال";foreach(var p in ps)ws.Cell(n,c++).Value=scoreList.FirstOrDefault(x=>x.SupplierPartId==m.Id&&x.PaymentParameterId==p.Id)?.Score??1m;n++;}Style(ws);return Bytes(wb);}
 public byte[] SupplierSummary(IEnumerable<(string Supplier,decimal Amount,int InvoiceCount)> rows){using var wb=new XLWorkbook();var ws=wb.Worksheets.Add("خلاصه تامین‌کنندگان");ws.Cell(1,1).Value="تامین کننده";ws.Cell(1,2).Value="مبلغ تخصیص یافته";ws.Cell(1,3).Value="تعداد رسید";var n=2;foreach(var x in rows){ws.Cell(n,1).Value=x.Supplier;ws.Cell(n,2).Value=x.Amount;ws.Cell(n,3).Value=x.InvoiceCount;n++;}Style(ws);return Bytes(wb);}
 static Dictionary<string,int> Headers(IXLRow r)=>r.CellsUsed().ToDictionary(x=>Norm(x.GetString()),x=>x.Address.ColumnNumber,StringComparer.OrdinalIgnoreCase);
 static string Norm(string s)=>(s??"").Trim().Replace("ي","ی").Replace("ك","ک").ToLowerInvariant();static string Cell(IXLWorksheet ws,int r,int c)=>ws.Cell(r,c).GetString().Trim();static void Require(Dictionary<string,int> h,List<string> e,string n){if(!h.ContainsKey(Norm(n)))e.Add($"ستون «{n}» در فایل Excel وجود ندارد.");}
 static bool Bool(string s)=>new[]{"فعال","بله","1","true","yes"}.Contains(Norm(s));static decimal ReadDecimal(IXLCell c){if(c.TryGetValue<decimal>(out var d))return d;var s=PersianDateService.ToLatinDigits(c.GetString()).Replace(",","").Replace("٬","");if(decimal.TryParse(s,out d))return d;throw new FormatException();}
 static void Style(IXLWorksheet ws){var u=ws.RangeUsed();if(u==null)return;u.FirstRow().Style.Font.Bold=true;u.FirstRow().Style.Fill.BackgroundColor=XLColor.LightGray;u.SetAutoFilter();ws.Columns().AdjustToContents();}static byte[] Bytes(XLWorkbook wb){using var m=new MemoryStream();wb.SaveAs(m);return m.ToArray();}
}
public record PartImportRow(int RowNumber,string Code,string Title,int TypeId,bool IsActive);public record SupplierImportRow(int RowNumber,string Code,string Title,decimal InitialClaimAmount,List<int> ActivityIds,bool IsActive);public record SupplierPartImportRow(int RowNumber,int SupplierId,int PartId,decimal SupplyCapacity,int ContractSettlementDays,bool IsActive);
